"""Embedded epidemiology snapshot used when runtime file access is unavailable."""

from __future__ import annotations

import base64
import gzip
import json
from typing import Any

BUNDLED_REPORT_GZ_B64 = """"""


def load_embedded_report_snapshot() -> dict[str, Any]:
    payload = gzip.decompress(base64.b64decode(BUNDLED_REPORT_GZ_B64))
    report = json.loads(payload.decode('utf-8'))
    if not isinstance(report, dict):
        raise ValueError('Snapshot embarcado inválido.')
    return report
